import { labelsDueAt, RecurrenceRule } from './solution';

function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function throwsRange(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: expected RangeError`);
}

const rules: RecurrenceRule[] = [
  { label: ' every-three ', period: 3, offset: 1 },
  { label: 'five', period: 5, offset: 0 },
  { label: 'late', period: 4, offset: 3 },
  { label: 'one', period: 1, offset: 0 }
];
const snapshot = JSON.stringify(rules);
deepEqual(labelsDueAt(0, rules), ['five', 'one'], 'rules firing at zero');
deepEqual(labelsDueAt(1, rules), [' every-three ', 'one'], 'offset fires exactly and label is not normalized');
deepEqual(labelsDueAt(3, rules), ['late', 'one'], 'nonzero offset formula');
deepEqual(labelsDueAt(4, rules), [' every-three ', 'one'], 'period after offset');
deepEqual(labelsDueAt(10, rules), [' every-three ', 'five', 'one'], 'results retain input order');
deepEqual(JSON.stringify(rules), snapshot, 'rules are not mutated');
const first = labelsDueAt(2, rules);
const second = labelsDueAt(2, rules);
assert(first !== second, 'each result is a new array');

deepEqual(labelsDueAt(0, []), [], 'empty rules are valid');
for (const tick of [-1, 1.5, Number.NaN, Number.POSITIVE_INFINITY, Number.MAX_SAFE_INTEGER + 1]) {
  throwsRange(() => labelsDueAt(tick, []), `invalid tick ${String(tick)}`);
}
throwsRange(() => labelsDueAt(0, [{ label: ' ', period: 1, offset: 0 }]), 'blank label');
throwsRange(() => labelsDueAt(0, [{ label: 'x', period: 1, offset: 0 }, { label: 'x', period: 2, offset: 0 }]), 'duplicate label');
for (const period of [0, -1, 1.5, Number.NaN, Number.MAX_SAFE_INTEGER + 1]) {
  throwsRange(() => labelsDueAt(0, [{ label: 'x', period, offset: 0 }]), 'invalid period');
}
for (const offset of [-1, 3, 1.5, Number.NaN, Number.MAX_SAFE_INTEGER + 1]) {
  throwsRange(() => labelsDueAt(0, [{ label: 'x', period: 3, offset }]), 'invalid offset');
}
// Even a rule that could not fire must still be validated.
throwsRange(() => labelsDueAt(0, [
  { label: 'valid', period: 2, offset: 1 },
  { label: 'invalid', period: 4, offset: 4 }
]), 'all rules are validated before results are determined');

